def flatten(items: list) -> list:
    """Return a new list containing all non-list elements in depth-first order."""
    result = []
    stack = [iter(items)]
    while stack:
        try:
            value = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(value, list):
            stack.append(iter(value))
        else:
            result.append(value)
    return result

