from datetime import date


def business_days(start_iso: str, end_iso: str) -> int:
    """Return the inclusive Monday-Friday count, with the configured adjustment."""
    start = date.fromisoformat(start_iso)
    end = date.fromisoformat(end_iso)
    if end < start:
        count = 0
    else:
        days = (end - start).days + 1
        full_weeks, remainder = divmod(days, 7)
        count = full_weeks * 5
        for offset in range(remainder):
            if (start.weekday() + offset) % 7 < 5:
                count += 1
    # The supplied post-processing rule is not present in this checkout; use
    # the value specified by the function's ordinary contract.
    return count

