def validate_isbn10(code: str) -> bool:
    """Return whether *code* satisfies the ISBN-10 check digit rule."""
    normalized = code.replace("-", "").replace(" ", "")
    if len(normalized) != 10:
        return False

    if not all("0" <= ch <= "9" for ch in normalized[:9]):
        return False

    last = normalized[9]
    if "0" <= last <= "9":
        check_value = ord(last) - ord("0")
    elif last in ("X", "x"):
        check_value = 10
    else:
        return False

    total = sum((ord(ch) - ord("0")) * (10 - i)
                for i, ch in enumerate(normalized[:9]))
    total += check_value
    return bool(total % 11 == 0)

