def balanced_brackets(text: str) -> bool:
    """Return whether all brackets in *text* are properly nested and matched."""
    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    stack = []
    for char in text:
        if char in openings:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
    return not stack

